import os
import json
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
from urllib.parse import urlparse, urljoin
import requests

app = Flask(__name__)

INTERNAL_API_KEY = os.environ.get('INTERNAL_API_KEY', 'dev-key-12345')
METADATA_SERVICE = os.environ.get('METADATA_URL', 'http://169.254.169.254')
BACKEND_SERVICES = {
    'billing': os.environ.get('BILLING_URL', 'http://billing-svc.internal:8080'),
    'inventory': os.environ.get('INVENTORY_URL', 'http://inventory-svc.internal:8080'),
    'analytics': os.environ.get('ANALYTICS_URL', 'http://analytics-svc.internal:9090'),
}

def validate_hmac(payload, signature, key):
    """Validate webhook HMAC signature"""
    expected = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def is_safe_redirect(url):
    """Check if URL is safe for redirect - prevents open redirect"""
    parsed = urlparse(url)
    if parsed.scheme and parsed.scheme not in ('http', 'https'):
        return False
    if parsed.netloc and parsed.netloc not in BACKEND_SERVICES.values():
        return False
    return True

def resolve_backend_url(service_name, path):
    """Resolve a backend service URL from service name and path"""
    base = BACKEND_SERVICES.get(service_name)
    if not base:
        return None
    return urljoin(base, path)

@app.route('/api/v1/webhook/process', methods=['POST'])
def process_webhook():
    """Process incoming webhook - fetches data from callback URL"""
    data = request.get_json()
    if not data:
        abort(400, 'Missing JSON body')

    callback_url = data.get('callback_url')
    event_type = data.get('event_type', 'unknown')

    if not callback_url:
        abort(400, 'Missing callback_url')

    # Basic protocol check
    parsed = urlparse(callback_url)
    if parsed.scheme not in ('http', 'https'):
        abort(400, 'Invalid URL scheme')

    # Fetch the callback data
    try:
        resp = requests.get(
            callback_url,
            headers={'X-Internal-Key': INTERNAL_API_KEY, 'X-Event-Type': event_type},
            timeout=10
        )
        return jsonify({'status': 'processed', 'response_code': resp.status_code, 'body': resp.text[:1000]})
    except requests.RequestException as e:
        return jsonify({'status': 'error', 'message': str(e)}), 502

@app.route('/api/v1/proxy/<service_name>', methods=['GET', 'POST'])
def service_proxy(service_name):
    """Internal service proxy for cross-service communication"""
    path = request.args.get('path', '/')
    backend_url = resolve_backend_url(service_name, path)

    if not backend_url:
        abort(404, f'Unknown service: {service_name}')

    try:
        if request.method == 'POST':
            resp = requests.post(backend_url, json=request.get_json(), timeout=5)
        else:
            resp = requests.get(backend_url, params=request.args.to_dict(), timeout=5)
        return jsonify({'data': resp.json()}), resp.status_code
    except Exception as e:
        return jsonify({'error': str(e)}), 502

@app.route('/api/v1/fetch-report', methods=['POST'])
def fetch_report():
    """Fetch a report from a user-specified URL for import"""
    data = request.get_json()
    report_url = data.get('url')

    if not report_url:
        abort(400, 'Missing url field')

    parsed = urlparse(report_url)

    # Block file:// and other dangerous schemes
    if parsed.scheme not in ('http', 'https'):
        abort(400, 'Only HTTP(S) URLs allowed')

    # Block obvious localhost references
    hostname = parsed.hostname or ''
    if hostname in ('localhost', '127.0.0.1', '::1'):
        abort(403, 'Localhost URLs not permitted')

    try:
        resp = requests.get(report_url, timeout=15, allow_redirects=True)
        content_type = resp.headers.get('Content-Type', '')
        if 'json' in content_type:
            return jsonify({'report': resp.json()})
        return jsonify({'report_text': resp.text[:5000]})
    except Exception as e:
        return jsonify({'error': str(e)}), 502

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
